import sympy
from sympy import eye, zeros

I2 = eye(2)
I3 = eye(3)
O2 = zeros(2, 2)
O3 = zeros(3, 3)

CONDITION_LABELS = [
    "H_1: G is the special linear group SL(2, Z)",
    "H_2: A is the matrix with rows (1, 2) and (0, 1) in G",
    "H_3: H is the subgroup of G generated by A and B",
    "¬Q: H is not isomorphic to the free group of rank 2"
]

N_HYP = 3
NEG_Q_INDEX = 3

def conditions(witness):
    try:
        if isinstance(witness, tuple) and len(witness) == 2:
            A_wit, B_wit = witness
            if not isinstance(A_wit, sympy.Matrix):
                A_wit = sympy.Matrix(A_wit)
            h2 = (A_wit == sympy.Matrix([[1, 2], [0, 1]]))
            B = B_wit
        elif isinstance(witness, dict):
            A_wit = witness.get('A', sympy.Matrix([[1, 2], [0, 1]]))
            if not isinstance(A_wit, sympy.Matrix):
                A_wit = sympy.Matrix(A_wit)
            h2 = (A_wit == sympy.Matrix([[1, 2], [0, 1]]))
            B = witness.get('B', witness)
        else:
            B = witness
            h2 = True
    except Exception:
        B = witness
        h2 = False

    try:
        if not isinstance(B, sympy.Matrix):
            B = sympy.Matrix(B)
        h1 = False
        if B.shape == (2, 2):
            if all(sympy.sympify(x).is_integer for x in B):
                if B.det() == 1:
                    h1 = True
    except Exception:
        h1 = False

    h3 = True

    try:
        if not isinstance(B, sympy.Matrix):
            B = sympy.Matrix(B)
            
        A = sympy.Matrix([[1, 2], [0, 1]])
        
        def mul(M1, M2):
            a, b, c, d = M1
            e, f, g, h = M2
            return (a*e + b*g, a*f + b*h, c*e + d*g, c*f + d*h)
            
        def mat_to_tuple(M):
            return (int(M[0,0]), int(M[0,1]), int(M[1,0]), int(M[1,1]))
            
        I_tup = (1, 0, 0, 1)
        A_tup = mat_to_tuple(A)
        B_tup = mat_to_tuple(B)
        
        if A_tup == I_tup or B_tup == I_tup:
            neg_q = True
        else:
            A_inv = A.inv()
            B_inv = B.inv()
            A_inv_tup = mat_to_tuple(A_inv)
            B_inv_tup = mat_to_tuple(B_inv)
            
            seen = set()
            seen.add(I_tup)
            
            inverses = {1: 2, 2: 1, 3: 4, 4: 3}
            gens = {1: A_tup, 2: A_inv_tup, 3: B_tup, 4: B_inv_tup}
            
            q = [ (I_tup, 0) ]
            neg_q = False
            max_depth = 12
            
            for depth in range(max_depth):
                next_q = []
                for mat, last_gen in q:
                    for g_idx, g_mat in gens.items():
                        if inverses[g_idx] == last_gen:
                            continue
                        
                        new_mat = mul(mat, g_mat)
                        if new_mat in seen:
                            neg_q = True
                            break
                        seen.add(new_mat)
                        next_q.append((new_mat, g_idx))
                    if neg_q:
                        break
                if neg_q:
                    break
                q = next_q
    except Exception:
        neg_q = False

    return [h1, h2, h3, neg_q]